import { readFileSync, existsSync, mkdirSync, writeFileSync, statSync, appendFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { homedir } from "node:os";
import { fileURLToPath } from "node:url";
const __dirname = dirname(fileURLToPath(import.meta.url));
const RULES_PATH = join(__dirname, "flow-rules.json");
export function resolveRulesPath() {
    return RULES_PATH;
}

const GUARD_AGENTS_TEMPLATE = [
    "# AGENTS.md",
    "",
    "> Auto-generated by vibeOS Project Guard. Defines rules for AI agents working on this project.",
    "",
    "## CRITICAL — ASK BEFORE CHANGING CODE",
    "",
    "NEVER modify any file without explicit user permission.",
    "If you are an LLM: DO NOT LGTM, DO NOT \"fix\", DO NOT \"clean up\",",
    'DO NOT "refactor", DO NOT "optimize", DO NOT "modernize". ASK FIRST.',
    "",
    "## PROTECTED FILES",
    "",
    "Do not modify these files without explicit user permission:",
    "- AGENTS.md (this file)",
    "- README.md",
    "",
].join("\n");

const GUARD_README_TEMPLATE = (name, techStack) => {
    const stackLine = techStack.length > 0 ? techStack.map((t) => `\`${t}\``).join(", ") : "(auto-detected on next session)";
    return [
        `# ${name}`,
        "",
        "## Tech Stack",
        "",
        stackLine,
        "",
        "## Features",
        "",
        "(Feature list maintained by vibeOS — run `trinity guard` to refresh)",
        "",
        "## Getting Started",
        "",
        "```bash",
        "# Clone and install dependencies",
        "```",
        "",
    ].join("\n");
};

export function ensureProjectDocs(dir, techStack) {
    const created = [];
    const skipped = [];
    const agentsPath = join(dir, "AGENTS.md");
    const readmePath = join(dir, "README.md");
    try {
        if (!existsSync(agentsPath)) {
            try {
                writeFileSync(agentsPath, GUARD_AGENTS_TEMPLATE, "utf-8");
                created.push("AGENTS.md");
                console.error("[vibeOS] Project Guard: created AGENTS.md");
            }
            catch (err) {
                console.error(`[vibeOS] Project Guard: failed to create AGENTS.md: ${err.message}`);
            }
        }
        else {
            skipped.push("AGENTS.md");
        }
    }
    catch { }
    try {
        if (!existsSync(readmePath)) {
            const name = dir ? dir.split("/").pop() || "Project" : "Project";
            const stack = techStack || [];
            const content = GUARD_README_TEMPLATE(name, stack);
            try {
                writeFileSync(readmePath, content, "utf-8");
                created.push("README.md");
                console.error("[vibeOS] Project Guard: created README.md");
            }
            catch (err) {
                console.error(`[vibeOS] Project Guard: failed to create README.md: ${err.message}`);
            }
        }
        else {
            skipped.push("README.md");
        }
    }
    catch { }
    return { created, skipped };
}
const STATE_FILE = join(homedir(), ".claude/delegation-state.json");
const FLOW_TODO_FILE = join(homedir(), ".claude/flow-todo-queue.jsonl");
const FLOW_DEDUP_FILE = join(homedir(), ".claude/.flow-dedup-keys.json");
const MAX_FLOW_TODOS = 200;
const _flowWarnsSeen = new Set();
let _stateWriter = null;
export function setFlowStateWriter(writer) {
    _stateWriter = typeof writer === "function" ? writer : null;
}
// Persist flow dedup keys across restarts to avoid re-warnings
function loadFlowDedupKeys() {
    try {
        if (existsSync(FLOW_DEDUP_FILE)) {
            const raw = readFileSync(FLOW_DEDUP_FILE, "utf-8");
            const keys = JSON.parse(raw);
            if (Array.isArray(keys)) {
                for (const k of keys)
                    _flowWarnsSeen.add(k);
            }
        }
    }
    catch { }
}
function persistFlowDedupKey(key) {
    try {
        mkdirSync(dirname(FLOW_DEDUP_FILE), { recursive: true });
        let keys = [];
        if (existsSync(FLOW_DEDUP_FILE)) {
            try {
                keys = JSON.parse(readFileSync(FLOW_DEDUP_FILE, "utf-8"));
            }
            catch { }
            if (!Array.isArray(keys))
                keys = [];
        }
        if (!keys.includes(key)) {
            keys.push(key);
            if (keys.length > 1000)
                keys = keys.slice(-500);
            writeFileSync(FLOW_DEDUP_FILE, JSON.stringify(keys), "utf-8");
        }
    }
    catch { }
}
loadFlowDedupKeys();
let _cachedRules = null;
let _rulesMtime = 0;
function loadRules() {
    const rulesPath = resolveRulesPath();
    try {
        const mtime = _cachedRules ? statSync(rulesPath).mtimeMs : 0;
        if (_cachedRules && mtime === _rulesMtime)
            return _cachedRules;
        if (!existsSync(rulesPath)) {
            _cachedRules = [];
            return _cachedRules;
        }
        const j = JSON.parse(readFileSync(rulesPath, "utf-8"));
        _cachedRules = j.rules || [];
        _rulesMtime = mtime;
        return _cachedRules;
    }
    catch {
        _cachedRules = [];
        return _cachedRules;
    }
}
function recordFlowWarn(hit) {
    try {
        let state = {};
        if (existsSync(STATE_FILE)) {
            try {
                state = JSON.parse(readFileSync(STATE_FILE, "utf-8"));
            }
            catch { }
        }
        else {
            mkdirSync(dirname(STATE_FILE), { recursive: true });
        }
        state.flow_warns ??= [];
        state.flow_warns.push({
            at: new Date().toISOString(),
            sid: process.pid || "?",
            rule_id: hit.id,
            severity: hit.severity,
            filePath: hit.filePath,
            description: hit.description,
        });
        if (state.flow_warns.length > 500) {
            state.flow_warns = state.flow_warns.slice(-500);
        }
        if (_stateWriter)
            _stateWriter(state);
        else {
            const existing = JSON.parse(existsSync(STATE_FILE) ? readFileSync(STATE_FILE, "utf-8") : "{}");
            const merged = { ...existing, ...state };
            writeFileSync(STATE_FILE, JSON.stringify(merged, null, 2));
        }
    }
    catch { }
}
export function checkFlowRules({ tool, filePath, content }) {
    const rules = loadRules();
    const hits = [];
    const toolName = String(tool || "").trim().toLowerCase();
    for (const rule of rules) {
        const triggerName = String(rule.trigger || "").trim().toLowerCase();
        if (triggerName !== toolName)
            continue;
        const target = toolName === "write" ? (filePath || "") : (content || filePath || "");
        let re;
        try {
            re = new RegExp(rule.pattern);
        }
        catch {
            continue;
        }
        if (!re.test(target))
            continue;
        const key = `${rule.id}::${filePath || ""}`;
        if (_flowWarnsSeen.has(key)) {
            hits.push({ ...rule, filePath, deduped: true });
            continue;
        }
        _flowWarnsSeen.add(key);
        persistFlowDedupKey(key);
        const hit = { ...rule, filePath, deduped: false };
        hits.push(hit);
        recordFlowWarn(hit);
    }
    return hits;
}
export function getFlowWarns() {
    try {
        if (!existsSync(STATE_FILE))
            return [];
        const s = JSON.parse(readFileSync(STATE_FILE, "utf-8"));
        return s?.flow_warns || [];
    }
    catch {
        return [];
    }
}
export function getSessionFlowCounts() {
    const counts = { warn: 0, hint: 0, flag: 0 };
    for (const key of _flowWarnsSeen) {
        const rules = loadRules();
        const [ruleId] = key.split("::");
        const rule = rules.find((r) => r.id === ruleId);
        if (rule && counts[rule.severity] !== undefined)
            counts[rule.severity]++;
    }
    return counts;
}
export function resetForTest(rules) {
    _cachedRules = rules;
    _flowWarnsSeen.clear();
    // Sync mtime so loadRules() returns test rules instead of reloading from file.
    try {
        _rulesMtime = statSync(resolveRulesPath()).mtimeMs;
    }
    catch { }
}
export function resetAll() {
    _flowWarnsSeen.clear();
    _cachedRules = null;
    _rulesMtime = 0;
}
export function addFlowRule(rule) {
    const rules = loadRules();
    rules.push(rule);
    writeFileSync(resolveRulesPath(), JSON.stringify({ rules }, null, 2), "utf-8");
    _cachedRules = rules;
    _rulesMtime = statSync(resolveRulesPath()).mtimeMs;
}
export function recordFlowTodo({ filePath, content }) {
    try {
        mkdirSync(dirname(FLOW_TODO_FILE), { recursive: true });
        // Extract TODO/FIXME lines from content (line-by-line for reliability).
        const todoRe = /(TODO|FIXME|HACK)[\s:]+(.+)$/i;
        const todos = [];
        for (const line of content.split("\n")) {
            const m = line.match(todoRe);
            if (m) {
                todos.push({ type: m[1], text: m[2].trim() });
            }
        }
        if (todos.length === 0)
            return 0;
        const entry = JSON.stringify({
            at: new Date().toISOString(),
            filePath,
            todos,
        }) + "\n";
        appendFileSync(FLOW_TODO_FILE, entry);
        // Prune to keep file bounded.
        try {
            const lines = readFileSync(FLOW_TODO_FILE, "utf-8").trim().split("\n").filter(Boolean);
            if (lines.length > MAX_FLOW_TODOS) {
                writeFileSync(FLOW_TODO_FILE, lines.slice(-Math.floor(MAX_FLOW_TODOS / 2)).join("\n") + "\n");
            }
        }
        catch { }
        console.error(`[flow-enforcer] 📋 Extracted ${todos.length} TODO(s) from ${filePath} → flow-todo-queue.jsonl`);
        return todos.length;
    }
    catch {
        return 0;
    }
}
